102	template <typename Derived>
103	class ITokenizerHelper : public ITokenizer
104	{
105	protected:
106	    explicit ITokenizerHelper(Type type_) : ITokenizer(type_) {}
107	
108	    const char * getTokenizerName() const override { return Derived::getName(); }
109	    const char * getTokenizerExternalName() const override { return Derived::getExternalName(); }
110	
111	    std::unique_ptr<ITokenizer> clone() const override
112	    {
113	        return std::make_unique<Derived>(*static_cast<const Derived *>(this));
114	    }
115	
116	    void stringToBloomFilter(const char * data, size_t length, BloomFilter & bloom_filter) const override
117	    {
118	        size_t cur = 0;
119	        size_t token_start = 0;
120	        size_t token_len = 0;
121	
122	        while (cur < length && static_cast<const Derived *>(this)->nextInString(data, length, cur, token_start, token_len))
123	            bloom_filter.add(data + token_start, token_len);
124	    }
125	
126	    void stringLikeToBloomFilter(const char * data, size_t length, BloomFilter & bloom_filter) const override
127	    {
128	        size_t cur = 0;
129	        String token;
130	
131	        while (cur < length && static_cast<const Derived *>(this)->nextInStringLike(data, length, cur, token))
132	            bloom_filter.add(token.c_str(), token.size());
133	    }
134	
135	    void stringToTokens(const char * data, size_t length, std::vector<String> & tokens) const override
136	    {
137	        size_t cur = 0;
138	        size_t token_start = 0;
139	        size_t token_len = 0;
140	
141	        while (cur < length && static_cast<const Derived *>(this)->nextInString(data, length, cur, token_start, token_len))
142	            tokens.push_back({data + token_start, token_len});
143	    }
144	
145	    void stringLikeToTokens(const char * data, size_t length, std::vector<String> & tokens) const override
146	    {
147	        size_t cur = 0;
148	        String token;
149	
150	        while (cur < length && static_cast<const Derived *>(this)->nextInStringLike(data, length, cur, token))
151	            tokens.push_back(token);
152	    }
153	
154	    std::vector<String> compactTokens(const std::vector<String> & tokens) const override
155	    {
156	        std::unordered_set<String> unique_tokens(tokens.begin(), tokens.end());
157	        return std::vector<String>(unique_tokens.begin(), unique_tokens.end());
158	    }
159	};
